import java.util.*;

public class Main {
    static final int INF = 10000000;
    static final int N = 210;
    static final int M = 21000;

    static class Edge {
        int v, w;
        Edge(int v, int w) {
            this.v = v; this.w = w;
        }
    }

    static int[] adj = new int[M], head = new int[N], e;
    static Edge[] edges = new Edge[M];
    static int[] dist = new int[N], q = new int[N*2], arc = new int[N], gap = new int[N], inq = new int[N], pre = new int[N];
    static int S, T;

    static String[] str = new String[12], str2 = new String[12];
    static int[][] sci = new int[12][12], ca = new int[12][12], stone = new int[62][12][12];
    static int[][][][][] dp = new int[62][12][12][12][12];
    static int[][] dir = {{-1,0},{1,0},{0,-1},{0,1}};
    static int n, t;

    static int[] vis = new int[12*12];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt(); t = sc.nextInt();

        for (int i = 1; i <= n; i++) {
            str[i] = sc.next();
            for (int j = 1; j <= n; j++) {
                char ch = str[i].charAt(j - 1);
                if (ch == 'Z') {
                    stone[0][i][j] = 2;
                } else if (ch == 'Y') {
                    stone[0][i][j] = 1;
                } else {
                    sci[i][j] = ch - '0';
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            str2[i] = sc.next();
            for (int j = 1; j <= n; j++) {
                char ch = str2[i].charAt(j - 1);
                if (ch >= '0' && ch <= '9') {
                    ca[i][j] = ch - '0';
                }
            }
        }

        expand();

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (sci[i][j] != 0) {
                    Arrays.fill(vis, 0);
                    dfs(i, j, i, j, 0);
                }
            }
        }

        for (int k = 1; k <= t; k++) {
            for (int x = 1; x <= n; x++) {
                for (int y = 1; y <= n; y++) {
                    for (int nx = 1; nx <= n; nx++) {
                        for (int ny = 1; ny <= n; ny++) {
                            dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];
                        }
                    }
                }
            }
        }

        S = 0;
        T = n * n * 2 + 1;
        Arrays.fill(head, -1);
        e = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int u = (i - 1) * n + j;
                addEdge(S, u, sci[i][j]);
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int v = n * n + (i - 1) * n + j;
                addEdge(v, T, ca[i][j]);
            }
        }

        for (int x = 1; x <= n; x++) {
            for (int y = 1; y <= n; y++) {
                for (int nx_ = 1; nx_ <= n; nx_++) {
                    for (int ny = 1; ny <= n; ny++) {
                        if (sci[x][y] != 0 && ca[nx_][ny]) {
                            if (dp[t][x][y][nx_][ny] != 0) {
                                int u = (x - 1) * n + y;
                                int v = n * n + (nx_ - 1) * n + ny;
                                addEdge(u, v, INF);
                            }
                        }
                    }
                }
            }
        }

        int ans = sap(S, T);
        System.out.println(ans);
        sc.close();
    }

    static void expand() {
        for (int k = 1; k <= t; k++) {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (stone[k - 1][i][j] == 1)
                        stone[k][i][j] = 1;
                    else if (stone[k - 1][i][j] == 2)
                        stone[k][i][j] = 2;
                    else {
                        for (int z = 0; z < 4; z++) {
                            int nx = i + dir[z][0], ny = j + dir[z][1];
                            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                                if (stone[k - 1][nx][ny] == 2)
                                    stone[k][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }

    static void dfs(int x, int y, int nowx, int nowy, int k) {
        vis[(nowx - 1) * n + nowy] = 1;
        dp[k][x][y][nowx][nowy] = 1;
        if (k >= t || stone[k][nowx][nowy] != 0)
            return;
        for (int z = 0; z < 4; z++) {
            int nx = nowx + dir[z][0], ny = nowy + dir[z][1];
            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && vis[(nx - 1) * n + ny] == 0) {
                if (stone[k][nx][ny] != 0)
                    continue;
                dfs(x, y, nx, ny, k + 1);
            }
        }
    }

    static int sap(int s, int t) {
        Arrays.fill(arc, -1);
        Arrays.fill(pre, -1);
        int qf = 0, qr = 0;
        q[qr++] = t;
        inq[t] = 1;
        gap[0]++;
        dist[t] = 0;

        while (qf < qr) {
            int u = q[qf++];
            for (int i = head[u]; i != -1; i = getAdj(i)) {
                if (edges[i].w != 0 && inq[edges[i].v] == 0) {
                    int v = edges[i].v;
                    q[qr++] = v;
                    inq[v] = 1;
                    dist[v] = dist[u] + 1;
                    gap[dist[v]]++;
                    arc[v] = i;
                }
            }
        }

        int low = INF, u = s, ans = 0;
        pre[s] = s;
        while (dist[s] < t) {
            boolean flag = false;
            for (int i = arc[u]; i != -1; i = getAdj(i)) {
                if (edges[i].w > 0 && dist[edges[i].v] + 1 == dist[u]) {
                    flag = true;
                    low = Math.min(low, edges[i].w);
                    pre[edges[i].v] = u;
                    u = edges[i].v;
                    if (u == t) {
                        while (u != s) {
                            int idx = pre[u];
                            int edgeIdx = getEdgeIdx(idx);
                            edges[edgeIdx].w -= low;
                            edges[edgeIdx ^ 1].w += low;
                            u = edgeFromIndex(idx);
                        }
                        ans += low;
                        low = INF;
                    }
                    break;
                }
            }
            if (flag)
                continue;
            int mindis = t + 1;
            for (int i = head[u]; i != -1; i = getAdj(i))
                if (edges[i].w != 0 && dist[edges[i].v] < mindis)
                    mindis = dist[edges[i].v];
            gap[dist[u]]--;
            if (gap[dist[u]] == 0)
                return ans;
            dist[u] = mindis + 1;
            gap[dist[u]]++;
            u = pre[u];
        }
        return ans;
    }

    static void addEdge(int u, int v, int w) {
        edges[e[0]] = new Edge(v, w);
        adj[e[0]] = head[u];
        head[u] = e[0]++;
        edges[e[0]] = new Edge(u, 0);
        adj[e[0]] = head[v];
        head[v] = e[0]++;
    }

    static int getAdj(int i) {
        return adj[i];
    }

    static int getEdgeIdx(int idx) {
        return idx;
    }

    static int edgeFromIndex(int idx) {
        return edges[idx].v;
    }
}
